def sidebar_nav(items, icons=None, current=None, key="nav"):
    """Sidebar navigation. Icons come from ICON_PATHS by item name
    (dashboard / search / results / settings); other items fall back to
    the emoji passed in `icons`."""

    state_key = f"{key}_active_page"
    if state_key not in st.session_state:
        st.session_state[state_key] = current or items[0]

    icons = icons or [""] * len(items)
    rules = []

    for item in items:
        name = item.strip().lower()
        if name not in ICON_PATHS:
            continue
        slug = "".join(ch for ch in name if ch.isalnum())
        sel = (
            'section[data-testid="stSidebar"] '
            f'div[data-testid="stElementContainer"]:has(.nav-icon-{slug}) '
            '+ div[data-testid="stElementContainer"] '
            'div[data-testid="stButton"] button'
        )
        rules.append(f"""
        {sel} {{
            background-repeat: no-repeat !important;
            background-position: 14px center !important;
            background-size: 22px 22px !important;
            padding-left: 46px !important;
        }}
        {sel}[kind="secondary"] {{
            background-image: url("{_svg_uri(name, COLORS['text_muted'])}") !important;
        }}
        {sel}[kind="primary"] {{
            background-image: url("{_svg_uri(name, COLORS['accent'])}") !important;
        }}
        section[data-testid="stSidebar"][aria-expanded="false"]
        div[data-testid="stElementContainer"]:has(.nav-icon-{slug})
        + div[data-testid="stElementContainer"]
        div[data-testid="stButton"] button {{
            padding-left: 0 !important;
            background-position: center !important;
        }}
        """)

    if rules:
        st.markdown("<style>" + "".join(rules) + "</style>", unsafe_allow_html=True)

    for item, icon in zip(items, icons):
        name = item.strip().lower()
        is_active = st.session_state[state_key] == item

        if name in ICON_PATHS:
            slug = "".join(ch for ch in name if ch.isalnum())
            st.markdown(f'<span class="nav-icon-{slug}"></span>', unsafe_allow_html=True)
            label = item
        else:
            label = f"{icon}  {item}" if icon else item

        if st.button(
            label,
            key=f"{key}_btn_{item}",
            use_container_width=True,
            type="primary" if is_active else "secondary",
        ):
            st.session_state[state_key] = item
            st.rerun()

    return st.session_state[state_key]


def topbar(title, subtitle="Lead Scrapper Tool", user_label="Admin",
           user_role=None, notifications=0,
           search_placeholder="Search name, mobile, company..."):
    """Search bar + bell + admin pill across the top, page title below.
    Returns whatever was typed in the search bar."""

    c_search, c_bell, c_user = st.columns([6, 0.7, 1.7])

    with c_search:
        st.markdown('<span class="topsearch-marker"></span>', unsafe_allow_html=True)
        query = st.text_input(
            "Search", placeholder=search_placeholder,
            key="global_search", label_visibility="collapsed",
        )

    with c_bell:
        badge = (
            f'<span style="position:absolute;top:-5px;right:-5px;'
            f'background:{COLORS["accent"]};color:{COLORS["on_accent"]};'
            f'font-size:10px;font-weight:600;min-width:16px;height:16px;'
            f'border-radius:8px;display:flex;align-items:center;'
            f'justify-content:center;padding:0 4px;">{notifications}</span>'
            if notifications else ""
        )
        st.markdown(
            _h(f"""
            <div style="width:44px;height:44px;border-radius:12px;position:relative;
                        background:{COLORS['card_bg']};border:1px solid {COLORS['card_border']};
                        display:flex;align-items:center;justify-content:center;">
                {svg_icon('bell', COLORS['text_dark'], 22)}{badge}
            </div>
            """),
            unsafe_allow_html=True,
        )

    with c_user:
        initials = "".join([w[0] for w in user_label.split()][:2]).upper()
        role_html = (
            f'<div style="font-size:10px;color:{COLORS["text_muted"]};">{user_role}</div>'
            if user_role else ""
        )
        st.markdown(
            _h(f"""
            <div style="height:44px;display:inline-flex;align-items:center;gap:10px;
                        padding:0 12px 0 6px;border-radius:14px;
                        background:{COLORS['card_bg']};border:1px solid {COLORS['card_border']};">
                <div style="width:32px;height:32px;border-radius:50%;
                            background:{COLORS['accent']};color:{COLORS['on_accent']};
                            display:flex;align-items:center;justify-content:center;
                            font-weight:700;font-size:14px;">{initials}</div>
                <div style="line-height:1.1;">
                    <div style="font-size:14px;font-weight:600;
                                color:{COLORS['text_dark']};">{user_label}</div>
                    {role_html}
                </div>
                {svg_icon('chevron', COLORS['text_muted'], 16)}
            </div>
            """),
            unsafe_allow_html=True,
        )

    st.markdown(
        f"<hr style='margin-top:10px;margin-bottom:14px;border-color:{COLORS['card_border']};'>",
        unsafe_allow_html=True,
    )
    st.markdown(
        _h(f"""
        <div class="topbar-title">{title}</div>
        <div class="topbar-subtitle" style="margin-bottom:14px;">{subtitle}</div>
        """),
        unsafe_allow_html=True,
    )
    return query

def icon_stat_card(label, value, caption=None, icon="users", tone=None):
    """One icon-style stat card.

    icon: name from ICON_PATHS (users, calendar, building, plus, ...) or raw HTML.
    tone: orange | red | amber | green. Left as None, it follows the icon
          (users=orange, calendar=red, building=amber, plus=green).
    """
    t = TONES.get(tone or DEFAULT_TONE.get(icon, "orange"), TONES["orange"])
    icon_html = svg_icon(icon, t["fg"], 24) if icon in ICON_PATHS else icon
    caption_html = f'<div class="icon-card-caption">{caption}</div>' if caption else ""

    st.markdown(
        _h(f"""
        <div class="icon-card">
            <div class="icon-card-icon" style="width:52px;height:52px;min-width:52px;
                 border-radius:14px;background:linear-gradient(145deg,#FFFFFF,{t['bg']});
                 border:1px solid {t['fg']}33;box-shadow:0 4px 10px {t['fg']}22;">
                {icon_html}
            </div>
            <div>
                <div class="icon-card-label">{label}</div>
                <div class="icon-card-value">{value}</div>
                {caption_html}
            </div>
        </div>
        """),
        unsafe_allow_html=True,
    )


class panel:
    """Bordered card with the title inside (chart / table container).
    Styling is driven entirely by dashboard_style's CSS via a hidden marker,
    not by Streamlit's own container(border=True) — which renders differently
    (or not at all) across Streamlit versions."""

    def __init__(self, title=None):
        self.title = title
        self.container = st.container()

    def __enter__(self):
        self.container.__enter__()
        st.markdown('<span class="panel-marker"></span>', unsafe_allow_html=True)
        if self.title:
            st.markdown(f'<div class="dash-panel-title">{self.title}</div>',
                        unsafe_allow_html=True)
        return self.container

    def __exit__(self, exc_type, exc_val, exc_tb):
        return self.container.__exit__(exc_type, exc_val, exc_tb)

CHART_CONFIG = {"displayModeBar": False}
_LINE, _DONUT_NEW, _DONUT_DUP = "#F98A1B", "#FF9433", "#FFCBA8"
_TICK, _GRID = "#3A1D0D", "#F3D9C4"


def style_fig(fig, height=None):
    """Apply the orange theme to any Plotly figure."""
    fig.update_layout(
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Inter, Segoe UI, sans-serif", color=_TICK, size=13),
        margin=dict(l=10, r=10, t=10, b=10),
        height=height,
        colorway=[_DONUT_NEW, _DONUT_DUP],
    )
    fig.update_xaxes(
        gridcolor=_GRID, zeroline=False, showline=True,
        linecolor=_GRID, ticks="outside", tickcolor=_GRID, ticklen=6,
        tickfont=dict(color=_TICK, size=13, family="Inter, Segoe UI, sans-serif"),
    )
    fig.update_yaxes(
        gridcolor=_GRID, zeroline=False, showline=False,
        tickfont=dict(color=_TICK, size=13, family="Inter, Segoe UI, sans-serif"),
    )
    return fig


def leads_line_chart(labels, values, height=340):
    """'Leads Collected Overview' — orange line with soft area fill."""
    import plotly.graph_objects as go

    fig = go.Figure(go.Scatter(
        x=list(labels), y=list(values), mode="lines+markers",
        line=dict(color=_LINE, width=2.5),
        marker=dict(color=_LINE, size=6),
        fill="tozeroy", fillcolor="rgba(249,138,27,0.16)",
        hovertemplate="%{x}: %{y}<extra></extra>",
    ))
    style_fig(fig, height)
    fig.update_yaxes(rangemode="tozero")
    return fig


def new_vs_duplicate_donut(new, duplicate, height=340, total=None):
    """'Latest Search — New vs Duplicate' donut; centre shows `total` (default new+duplicate)."""
    import plotly.graph_objects as go

    total = new + duplicate if total is None else total
    fig = go.Figure(go.Pie(
        labels=["New", "Duplicate"], values=[new, duplicate],
        hole=0.6, sort=False, direction="clockwise", textinfo="percent",
        marker=dict(colors=[_DONUT_NEW, _DONUT_DUP], line=dict(color="#FFFDFA", width=2)),
        textfont=dict(color=["#FFFFFF", COLORS["text_dark"]], size=13),
    ))
    style_fig(fig, height)
    fig.update_layout(
        legend=dict(x=1, y=1, xanchor="right", font=dict(color=COLORS["text_dark"], size=14)),
        annotations=[dict(
            text=f"Total<br><b style='font-size:24px;color:{COLORS['text_dark']}'>{total}</b>",
            x=0.5, y=0.5, showarrow=False, font=dict(color=_TICK, size=14),
        )],
    )
    return fig

def show_chart(fig):
    """st.plotly_chart with Streamlit's own theme off and no toolbar."""
    st.plotly_chart(fig, use_container_width=True, theme=None, config=CHART_CONFIG)